"""Produce a fully explicit pending review packet; never adopt source prose."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
import correspondence as c


def draft(source,document):
    units=c.inventory(document);texts=dict(c.string_leaves(document));clauses=[];links=[]
    for i,unit in enumerate(units):
        identity='clause-'+str(i+1);text=texts[unit['selector']]
        clauses.append({'clause_id':identity,'source_selector':unit['selector'],'excerpt_sha256':unit['text_sha256'],'start_character':0,'disposition':'unresolved','forms':['unresolved'],'roles':['unresolved'],'formal_statement':None,'rationale':'Exact source content retained pending explicit role, form, signature and correspondence review; no assumption selected.'})
        links.append({'unit_id':unit['unit_id'],'clause_id':identity,'end_character':len(text),'excerpt':text})
    packet={'schema_version':'definition-assurance-correspondence/v1-candidate','authority_effect':'none','upstream_schema_sha256':c.r.digest((c.IMPL/'schemas/input-envelope.json').read_bytes()),'source_selection':'current','inventory_policy':'all-nonempty-string-leaves-in-voices-boundaries-scope-and-claim-ceiling/v1','interpretation':{'interpretation_id':'interpretation:'+source['definition_id'],'source':source,'scope':'scope:candidate-definition-review','declarations':[{'kind':'sort','symbol_id':'Record','scope':'scope:candidate-definition-review','domain_policy':'nonempty'}],'clauses':clauses,'depends_on':[],'relations':[],'assumptions':[],'populations':[],'logic_features':['unresolved'],'semantic_status':'unresolved','source_fidelity':'pending','profile_ref':None},'source_units':units,'correspondence':links,'dependency_links':[],'dependency_closure':{'status':'unresolved','review_ref':None,'unresolved_notes':['Semantic dependencies require separately bound explicit closure review; source mentions are leads only.']},'assumption_links':[],'source_precedence':{'normative_voice':'/voices/scientific_formal','conflicts':[],'review_ref':None},'review_packet':{'instances':[{'case_id':'instance-1','scenario':'A scoped concept record that its meaning owner can inspect.','expected_interpretation':'Classify the record independently from adopting the propositions it describes.','rationale':'Review example only; replace with a domain-realistic case before owner fidelity review.','related_clause_ids':[]}],'counterexamples':[{'case_id':'counterexample-1','scenario':'A record label is supplied without its defining conditions.','expected_interpretation':'The label alone establishes neither conformance nor truth.','rationale':'Review counterexample only; no model witness or provider result.','related_clause_ids':[]}],'known_losses':['All source units remain unresolved; no semantic translation or dependency-closure proof.','Character accounting does not split natural-language assertions or establish semantic completeness.'],'review_status':'pending','review_ref':None}}
    return packet


if __name__=='__main__':
    base=c.ROOT/'docs/plans/definition-formal-assurance/candidate/assurance-snapshots-v1';snapshot=json.loads((base/'current-snapshot.json').read_text());c.r.verify(snapshot,c.ROOT)
    row=next(row for row in snapshot['current_entries'] if row['definition_id']=='cal.definition.hypothesis');source={k:row[k] for k in ['definition_id','version_ref','path','sha256']};document=c.source_document(snapshot,source);packet=draft(source,document)
    packet['source_precedence']['conflicts']=[{'finding_id':'FID-HYP-001','selectors':['/voices/scientific_formal/normative_statement','/voices/scientific_formal/formal_expression'],'description':'The target normative statement describes investigation without adoption; the inherited formal expression describes a Premise adopted to proceed. Preserve both exact source fields; do not equate the identities.','status':'unresolved','owner_route':'role:definition-owner must decide source precedence and correspondence in a separate versioned decision.'}]
    packet['review_packet']['instances']=[{'case_id':'hypothesis-investigation','scenario':'A team records the proposition that a request queue caused the observed latency. Its posture is under investigation, with a test plan and falsification conditions; the team has not adopted the proposition as an assumption.','expected_interpretation':'A candidate Hypothesis record under the target normative statement; the proposition is not inserted into the reasoning premises.','rationale':'Separates investigation, adoption and established truth. The example is a review scenario, not real operational evidence.','related_clause_ids':[]}]
    packet['review_packet']['counterexamples']=[{'case_id':'adopted-working-premise','scenario':'A team explicitly assumes a latency baseline so planning can proceed, while recording that the baseline has not been established as true.','expected_interpretation':'A working Premise under the stated adoption posture; the inherited expression does not justify silently relabeling it as a Hypothesis or merging the definitions.','rationale':'Exposes FID-HYP-001 and requires a source-owner decision before a faithful whole-definition translation.','related_clause_ids':[]}]
    report=c.check(packet,snapshot,required_conflicts=['FID-HYP-001']);assert report['character_accounting_complete'] and report['status']=='correspondence-pending' and not report['semantic_ready']
    for name,obj in [('hypothesis-review-packet.json',packet),('hypothesis-correspondence-check.json',report)]:
        with (base/'units/A04'/name).open('x') as stream:json.dump(obj,stream,indent=2,sort_keys=True);stream.write('\n')
    print(json.dumps({'status':report['status'],'source_units':report['source_units'],'semantic_ready':report['semantic_ready'],'conflict':'FID-HYP-001'},indent=2))
